// Des: Encrypted contact backups: write-once weekly files, verify, restore
// Flo: rows as JSONL > seal with XChaCha20-Poly1305 (cont.key) > local latest by temp + rename, weekly file only if missing, keep cont_week_keep weeks > cloud put + download + open + compare, then drop old weeks > scrub rewrites every copy without the forgotten ids
// I/O: open Db + data dir + key (caller) > Bres counts; plain rows never reach disk outside the table, the cloud only ever sees sealed bytes; a failed upload leaves the flags alone so the next run retries
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const cstr = @import("st-cont-stor.zig"); const cryp = @import("ut-cryp-aead.zig"); const stor = @import("sy-clou-stor.zig"); const fail = @import("ru-fail-over.zig"); const roll = @import("ru-carz-roll.zig");
pub const CF = .{ .bkdr = "bkup", .adzz = "cont", .late = "cont-latest.enc", .wpre = "cont-", .wsuf = ".enc", .cpre = "cont/", .cwek = "cont/week-", .maxb = 64 << 20 };
pub const Bres = struct { rows: u32 = 0, sent: u8 = 0, week: u32 = 0, same: bool = false };
fn lineCont(body: []const u8) u32 { return @intCast(std.mem.count(u8, body, "\n")); }
fn codeOfzz(body: []const u8) i64 { return @bitCast(std.hash.Wyhash.hash(0xc0a7, body)); }
fn wekzName(aren: std.mem.Allocator, nowz: i64) ![]u8 { return std.fmt.allocPrint(aren, "{s}{d}{s}", .{ CF.wpre, roll.weekOfzz(nowz), CF.wsuf }); }
fn writAtom(aren: std.mem.Allocator, iozz: std.Io, dirx: []const u8, name: []const u8, body: []const u8) !void { const cwdz = std.Io.Dir.cwd(); try cwdz.createDirPath(iozz, dirx); const fina = try std.fs.path.join(aren, &.{ dirx, name }); const temp = try std.fmt.allocPrint(aren, "{s}.part", .{fina}); var filz = try cwdz.createFile(iozz, temp, .{}); filz.writeStreamingAll(iozz, body) catch |err3| { filz.close(iozz); return err3; }; filz.close(iozz); try cwdz.rename(temp, cwdz, fina, iozz); }
fn locaWeek(aren: std.mem.Allocator, iozz: std.Io, dirx: []const u8) ![][]const u8 { var list: std.ArrayList([]const u8) = .empty; var dirz = std.Io.Dir.cwd().openDir(iozz, dirx, .{ .iterate = true }) catch return list.toOwnedSlice(aren); defer dirz.close(iozz); var walk = try dirz.walk(aren); defer walk.deinit(); while (try walk.next(iozz)) |entr| { if (entr.kind == .file and std.mem.startsWith(u8, entr.basename, CF.wpre) and std.mem.endsWith(u8, entr.basename, CF.wsuf) and !std.mem.eql(u8, entr.basename, CF.late)) try list.append(aren, try aren.dupe(u8, entr.basename)); } const arrz = try list.toOwnedSlice(aren); std.mem.sort([]const u8, arrz, {}, struct { fn lesz(_: void, aaaa: []const u8, bbbb: []const u8) bool { return std.mem.order(u8, aaaa, bbbb) == .gt; } }.lesz); return arrz; }
pub fn backLoca(aren: std.mem.Allocator, iozz: std.Io, dbzz: *sqli.Dbzz, dirz: []const u8, keyz: [cryp.CF.keyb]u8, nowz: i64, keep: u32) !Bres { const plai = try cstr.rowsBuil(aren, dbzz); const seal = try cryp.sealPack(aren, iozz, keyz, plai, CF.adzz); const dirx = try std.fs.path.join(aren, &.{ dirz, CF.bkdr }); try writAtom(aren, iozz, dirx, CF.late, seal); const week = try wekzName(aren, nowz); const wpat = try std.fs.path.join(aren, &.{ dirx, week }); if (std.Io.Dir.cwd().statFile(iozz, wpat, .{})) |_| {} else |_| try writAtom(aren, iozz, dirx, week, seal); const weks = try locaWeek(aren, iozz, dirx); var idxz: usize = keep; while (idxz < weks.len) : (idxz += 1) std.Io.Dir.cwd().deleteFile(iozz, try std.fs.path.join(aren, &.{ dirx, weks[idxz] })) catch {}; return .{ .rows = lineCont(plai), .week = @intCast(@min(weks.len, keep)) }; }
pub fn backClou(aren: std.mem.Allocator, iozz: std.Io, dbzz: *sqli.Dbzz, stoq: stor.Stor, keyz: [cryp.CF.keyb]u8, nowz: i64, keep: u32) !Bres { const plai = try cstr.rowsBuil(aren, dbzz); var rslt: Bres = .{ .rows = lineCont(plai) }; if (plai.len == 0) { rslt.same = true; return rslt; } const codz = codeOfzz(plai); const wknz = roll.weekOfzz(nowz); const lasf = try fail.flagGetz(dbzz, "cont_snap"); const wekf = try fail.flagGetz(dbzz, "cont_week"); if (lasf == codz and wekf == wknz) { rslt.same = true; return rslt; } const seal = try cryp.sealPack(aren, iozz, keyz, plai, CF.adzz); const keyl = try std.fmt.allocPrint(aren, "{s}latest.enc", .{CF.cpre}); try stoq.put(stoq.ctx2, aren, iozz, keyl, seal); const back = try stoq.get(stoq.ctx2, aren, iozz, keyl); const open = cryp.sealOpen(aren, keyz, back, CF.adzz) catch return error.Fail; if (!std.mem.eql(u8, open, plai)) return error.Fail; rslt.sent = 1; if (wekf != wknz) { const keyw = try std.fmt.allocPrint(aren, "{s}{d}{s}", .{ CF.cwek, wknz, CF.wsuf }); try stoq.put(stoq.ctx2, aren, iozz, keyw, seal); const bac2 = try stoq.get(stoq.ctx2, aren, iozz, keyw); const ope2 = cryp.sealOpen(aren, keyz, bac2, CF.adzz) catch return error.Fail; if (!std.mem.eql(u8, ope2, plai)) return error.Fail; rslt.sent = 2; try fail.flagSetz(dbzz, "cont_week", wknz); } try fail.flagSetz(dbzz, "cont_snap", codz);
    const objs = try stoq.list(stoq.ctx2, aren, iozz, CF.cwek); var keys: std.ArrayList([]const u8) = .empty; for (objs) |objz| try keys.append(aren, objz.key2); std.mem.sort([]const u8, keys.items, {}, struct { fn lesz(_: void, aaaa: []const u8, bbbb: []const u8) bool { return std.mem.order(u8, aaaa, bbbb) == .gt; } }.lesz); rslt.week = @intCast(@min(keys.items.len, keep)); var idxz: usize = keep; while (idxz < keys.items.len) : (idxz += 1) stoq.del2(stoq.ctx2, aren, iozz, keys.items[idxz]) catch {}; return rslt; }
pub const Vres = struct { late: u32 = 0, fils: u32 = 0, bads: u32 = 0 };
pub fn backVeri(aren: std.mem.Allocator, iozz: std.Io, dirz: []const u8, keyz: [cryp.CF.keyb]u8) !Vres { var rslt: Vres = .{}; const dirx = try std.fs.path.join(aren, &.{ dirz, CF.bkdr }); const weks = try locaWeek(aren, iozz, dirx); var nams: std.ArrayList([]const u8) = .empty; try nams.append(aren, CF.late); for (weks) |wekz| try nams.append(aren, wekz); for (nams.items) |name| { const path = try std.fs.path.join(aren, &.{ dirx, name }); const blob = std.Io.Dir.cwd().readFileAlloc(iozz, path, aren, .limited(CF.maxb)) catch { if (std.mem.eql(u8, name, CF.late)) rslt.bads += 1; continue; }; rslt.fils += 1; const open = cryp.sealOpen(aren, keyz, blob, CF.adzz) catch { rslt.bads += 1; continue; }; if (std.mem.eql(u8, name, CF.late)) rslt.late = lineCont(open); } return rslt; }
pub fn backRest(aren: std.mem.Allocator, iozz: std.Io, dbzz: *sqli.Dbzz, keyz: [cryp.CF.keyb]u8, path: []const u8) !u32 { const blob = try std.Io.Dir.cwd().readFileAlloc(iozz, path, aren, .limited(CF.maxb)); const open = try cryp.sealOpen(aren, keyz, blob, CF.adzz); return cstr.rowsLoad(dbzz, aren, open); }
fn scruOnez(aren: std.mem.Allocator, iozz: std.Io, keyz: [cryp.CF.keyb]u8, blob: []const u8, cidz: []const []const u8) !?[]u8 { const open = cryp.sealOpen(aren, keyz, blob, CF.adzz) catch return null; var outp: std.ArrayList(u8) = .empty; var hits: u32 = 0; var iter = std.mem.splitScalar(u8, open, '\n'); while (iter.next()) |line| { if (line.len == 0) continue; var drop = false; for (cidz) |cidx| { const patz = try std.fmt.allocPrint(aren, "\"cidz\":\"{s}\"", .{cidx}); if (std.mem.indexOf(u8, line, patz) != null) drop = true; } if (drop) { hits += 1; continue; } try outp.appendSlice(aren, line); try outp.append(aren, '\n'); } if (hits == 0) return null; return try cryp.sealPack(aren, iozz, keyz, outp.items, CF.adzz); }
pub fn backScru(aren: std.mem.Allocator, iozz: std.Io, dirz: []const u8, stoq: ?stor.Stor, keyz: [cryp.CF.keyb]u8, cidz: []const []const u8) !u32 { var cont: u32 = 0; if (cidz.len == 0) return 0; const dirx = try std.fs.path.join(aren, &.{ dirz, CF.bkdr }); const weks = try locaWeek(aren, iozz, dirx); var nams: std.ArrayList([]const u8) = .empty; try nams.append(aren, CF.late); for (weks) |wekz| try nams.append(aren, wekz); for (nams.items) |name| { const path = try std.fs.path.join(aren, &.{ dirx, name }); const blob = std.Io.Dir.cwd().readFileAlloc(iozz, path, aren, .limited(CF.maxb)) catch continue; if (try scruOnez(aren, iozz, keyz, blob, cidz)) |fres| { try writAtom(aren, iozz, dirx, name, fres); cont += 1; } }
    if (stoq) |stoz| { const objs = try stoz.list(stoz.ctx2, aren, iozz, CF.cpre); for (objs) |objz| { const blob = stoz.get(stoz.ctx2, aren, iozz, objz.key2) catch continue; if (try scruOnez(aren, iozz, keyz, blob, cidz)) |fres| { try stoz.put(stoz.ctx2, aren, iozz, objz.key2, fres); cont += 1; } } } return cont; }
